import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { stat } from 'node:fs/promises';
import path from 'node:path';

const run = promisify(execFile);
const imageTypes = new Set(['.png', '.jpg', '.jpeg', '.bmp', '.gif', '.tif', '.tiff', '.webp']);
const script = String.raw`
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Runtime.WindowsRuntime
[Windows.Storage.StorageFile, Windows.Storage, ContentType=WindowsRuntime] | Out-Null
[Windows.Graphics.Imaging.BitmapDecoder, Windows.Graphics.Imaging, ContentType=WindowsRuntime] | Out-Null
[Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType=WindowsRuntime] | Out-Null
[Windows.Globalization.Language, Windows.Globalization, ContentType=WindowsRuntime] | Out-Null
$asTask = [System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object { $_.Name -eq 'AsTask' -and $_.IsGenericMethod -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation' + [char]96 + '1' } | Select-Object -First 1
function Await($op, $type) { $task = $asTask.MakeGenericMethod($type).Invoke($null, @($op)); $task.GetAwaiter().GetResult() }
$file = Await ([Windows.Storage.StorageFile]::GetFileFromPathAsync($env:CARB_OCR_PATH)) ([Windows.Storage.StorageFile])
$stream = Await ($file.OpenAsync([Windows.Storage.FileAccessMode]::Read)) ([Windows.Storage.Streams.IRandomAccessStream])
try {
  $decoder = Await ([Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($stream)) ([Windows.Graphics.Imaging.BitmapDecoder])
  if ($decoder.PixelWidth -gt 10000 -or $decoder.PixelHeight -gt 10000 -or ([long]$decoder.PixelWidth * $decoder.PixelHeight) -gt 40000000) { throw 'Image dimensions exceed OCR limit' }
  $bitmap = Await ($decoder.GetSoftwareBitmapAsync()) ([Windows.Graphics.Imaging.SoftwareBitmap])
  $results = @()
  foreach ($tag in @('zh-Hans-CN', 'en-US')) {
    $language = [Windows.Globalization.Language]::new($tag)
    if ([Windows.Media.Ocr.OcrEngine]::IsLanguageSupported($language)) {
      $engine = [Windows.Media.Ocr.OcrEngine]::TryCreateFromLanguage($language)
      if ($engine) { $result = Await ($engine.RecognizeAsync($bitmap)) ([Windows.Media.Ocr.OcrResult]); if ($result.Text) { $results += $result.Text } }
    }
  }
  if ($results.Count -eq 0 -and [Windows.Media.Ocr.OcrEngine]::AvailableRecognizerLanguages.Count -eq 0) { throw 'No Windows OCR language installed' }
  [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
  ($results | Select-Object -Unique) -join [Environment]::NewLine
} finally { $stream.Dispose() }
`;
const encodedScript = Buffer.from(script, 'utf16le').toString('base64');

/** Extract visible text locally; OCR cannot interpret layout or image semantics. */
export async function carbOcrAttachments(attachments) {
  if (process.platform !== 'win32') return '';
  const images = [...new Set((attachments ?? []).filter((p) => typeof p === 'string' && imageTypes.has(path.extname(p).toLowerCase())))];
  if (!images.length) return '';
  const notes = [];
  for (const file of images.slice(0, 15)) {
    try {
      const info = await stat(file);
      if (!info.isFile() || info.size > 20 * 1024 * 1024) throw new Error('unavailable or too large');
      const { stdout } = await run('powershell.exe', ['-NoProfile', '-NonInteractive', '-EncodedCommand', encodedScript], { env: { ...process.env, CARB_OCR_PATH: path.resolve(file) }, timeout: 20000, maxBuffer: 1024 * 1024, windowsHide: true, encoding: 'utf8' });
      const content = stdout.trim().slice(0, 12000);
      notes.push(`Image ${path.basename(file)}: ${content || '[No text detected]'}`);
    } catch {
      notes.push(`Image ${path.basename(file)}: [Local OCR failed or image is unavailable]`);
    }
  }
  return `Local OCR extracted the following text from image attachments. This is text only; it does not describe visual objects, layout, colors, or other image semantics. Do not claim to have visually inspected the images.\n${notes.join('\n\n')}`;
}
